(function () {
if (typeof config.username !== 'string') throw new Error('必须配置字符串 username');
var username = config.username.trim().replace(/^wxchannels:/, '').trim();
if (!username || username.indexOf('REPLACE_') >= 0) throw new Error('请在自动化配置中填写创作者 username');
if (!/@finder$/.test(username)) username += '@finder';
var url = (config.url || '').trim() || 'http://127.0.0.1:2022/api/channels/contact/feed/list';
var method = (config.method || 'GET').trim().toUpperCase() || 'GET';
if (['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS'].indexOf(method) < 0) throw new Error('列表接口 method 不支持');
var token = (config.token || '').trim();
return {username: username, url: url, method: method, authentication: {type: token ? 'bearer' : 'none', token: token}};
})()

(function () {
var result = output.download.download_result;
if (!result || (result.created !== true && result.skipped !== true)) throw new Error('下载工具没有返回已创建或已跳过结果');
return {oid: input.item.oid, created: result.created === true, skipped: result.skipped === true};
})()

(function () {
var results = output.download_missing.downloads;
if (!Array.isArray(results) || results.length !== input.pending.length) throw new Error('下载遍历结果不完整');
var submitted = 0, skipped = 0;
for (var i = 0; i < results.length; i++) {
  var result = results[i].output.inspect.download_status;
  if (result.oid !== input.pending[i].oid) throw new Error('下载遍历结果与视频不匹配');
  if (result.skipped) skipped += 1; else if (result.created) submitted += 1; else throw new Error('下载任务未创建');
}
return {submitted: submitted, skipped: skipped, response: input.fetch_enabled ? output.fetch_list.list_result.output.fetch_list.list_response : null};
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
var result = output.fetch_page.page_execution.output.merge_page.page_result;
state.submitted += result.submitted;
state.skipped += result.skipped;
state.pending = [];
return {state: state, response: result.response};
})()

(function () {
if (!(global.max_pages > 0) || Math.floor(global.max_pages) !== global.max_pages || !(global.max_videos > 0) || Math.floor(global.max_videos) !== global.max_videos) throw new Error('max_pages 和 max_videos 必须为正整数');
var data = global.page_response;
if (!data || !Array.isArray(data.object)) throw new Error('视频列表响应缺少 object');
if (!data.BaseResponse || data.BaseResponse.Ret === undefined || Number(data.BaseResponse.Ret) !== 0) throw new Error('视频列表 BaseResponse 返回错误');
var continue_flag = data.continue_flag;
if (continue_flag === undefined || continue_flag === null || !isFinite(Number(continue_flag))) throw new Error('视频列表缺少有效 continue_flag');
var state = JSON.parse(JSON.stringify(global.scan_state));
state.page += 1;
if (state.page > global.max_pages) throw new Error('超过 max_pages，本次同步未完成');
state.items = []; state.pending = []; state.all_existing = false;
var page_ids = {};
function id_string(value) {
  if (typeof value === 'number' && (!isFinite(value) || Math.floor(value) !== value || Math.abs(value) > 9007199254740991)) throw new Error('平台返回不安全的数字 ID，需要字符串 ID');
  return value === undefined || value === null ? '' : String(value);
}
function download_fields(value, keys) {
  var result = Object.assign({}, value);
  keys.forEach(function (key) {
    var snake = key.replace(/[A-Z]/g, function (letter) { return '_' + letter.toLowerCase(); });
    result[key] = value[snake];
    delete result[snake];
  });
  return result;
}
for (var i = 0; i < data.object.length; i++) {
  var item = data.object[i], desc = item.object_desc;
  if (!desc || !Array.isArray(desc.media)) throw new Error('视频缺少 object_desc.media');
  var media = desc.media;
  if (Number(desc.media_type) !== 4 && !media.some(function (m) { return Number(m.media_type) === 4; })) continue;
  var oid = id_string(item.id), nid = id_string(item.object_nonce_id);
  if (!oid || !nid) throw new Error('视频缺少 id 或 object_nonce_id');
  if (page_ids[oid]) continue;
  page_ids[oid] = true; state.seen_ids[oid] = true;
  var content = download_fields(item, ['objectNonceId', 'objectDesc', 'anchorContact']);
  content.id = oid; content.objectNonceId = nid;
  content.contact = download_fields(item.contact || data.contact || {}, ['headUrl', 'coverImgUrl', 'liveStatus']);
  if (!content.contact.username) content.contact.username = output.validate.creator.username;
  content.objectDesc = download_fields(desc, ['mediaType']);
  content.objectDesc.media = media.map(function (entry) {
    var media_item = download_fields(entry, ['mediaType', 'thumbUrl', 'coverUrl', 'decodeKey', 'urlToken', 'videoPlayLen', 'fileSize']);
    if (Array.isArray(media_item.spec)) media_item.spec = media_item.spec.map(function (spec) {
      return download_fields(spec, ['fileFormat', 'durationMs', 'videoBitrate', 'levelOrder']);
    });
    return media_item;
  });
  state.items.push({oid: oid, nid: nid, title: String(desc.description || ''), content: content});
}
if (Object.keys(state.seen_ids).length > global.max_videos) throw new Error('超过 max_videos，本次扫描未完成');
state.has_more = Number(continue_flag) !== 0;
state.next_cursor = data.last_buffer || '';
return state;
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
var response = output.check_videos.checks;
if (!response || !Array.isArray(response.list) || response.total !== state.items.length || response.list.length !== state.items.length) throw new Error('批量视频存在性检查结果不完整');
var checks = Object.create(null);
response.list.forEach(function (check) {
  if (!check || typeof check.content_id !== 'string' || Object.prototype.hasOwnProperty.call(checks, check.content_id) || typeof check.exists !== 'boolean' || typeof check.task_count !== 'number' || !isFinite(check.task_count) || check.task_count < 0 || Math.floor(check.task_count) !== check.task_count || check.exists !== (check.task_count > 0)) throw new Error('批量视频存在性检查结果无效');
  checks[check.content_id] = check;
});
state.pending = [];
for (var i = 0; i < state.items.length; i++) {
  var video = state.items[i], content_id = 'wxchannels:' + video.oid;
  if (!Object.prototype.hasOwnProperty.call(checks, content_id)) throw new Error('批量检查缺少视频 ' + video.oid);
  var check = checks[content_id];
  state.checked += 1;
  if (check.exists) state.skipped += 1;
  else {
    state.pending.push(video);
  }
}
state.all_existing = state.items.length > 0 && state.pending.length === 0;
return state;
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
state.fetch_enabled = state.has_more;
if (state.has_more) {
  if (typeof state.next_cursor !== 'string' || !state.next_cursor || state.visited_cursors.indexOf(state.next_cursor) >= 0) throw new Error('分页游标缺失或重复，停止以避免漏数据或无限循环');
  if (state.page >= global.max_pages) throw new Error('达到 max_pages 但仍有下一页，本次扫描未完成');
  state.cursor = state.next_cursor;
  state.visited_cursors.push(state.cursor);
}
return state;
})()

(function () {
var state = global.scan_state;
return {username: output.validate.creator.username, pages: state.page, videos: Object.keys(state.seen_ids).length, checked: state.checked, submitted: state.submitted, skipped: state.skipped, stop_reason: state.all_existing ? 'all_existing' : 'no_more_pages', note: '已存在指已有下载任务；submitted 表示任务已启动，不表示文件已下载完成；遇到整页已存在即停止翻页'};
})()

